853      public Node forVarDecl(VarDecl vd) {
854          boolean isMember = atTopLevelInsideTraitOrObject;
855          atTopLevelInsideTraitOrObject = false;
856          List<LValue> lhs = vd.getLhs();
857  
858          if (lhs.size() > 1) {
859              // Introduce a temporary, then initialize elements
860              // piece-by-piece.
861              if (vd.getInit().isNone()) return bug(vd, "Variable definition should have an expression.");
862              Expr init = vd.getInit().unwrap();
863              init = (Expr) recur(init);
864              lhs = (List<LValue>) recurOnListOfLValue(lhs);
865              ArrayList<VarDecl> newdecls = new ArrayList<VarDecl>(1 + lhs.size());
866              String temp = WellKnownNames.tempTupleName(vd);
867              Span at = NodeUtil.getSpan(vd);
868              VarDecl new_vd = NodeFactory.makeVarDecl(at, temp, init);
869              newdecls.add(new_vd);
870              // Each name reads its element from the temporary, which is
871              // declared where the names are: a member or a top-level variable.
872              Expr tempRef = (isMember ? new Member() : new Local()).replacement(ExprFactory.makeVarRef(at, temp));
873              int element_index = 0;
874              for (LValue lv : lhs) {
875                  Id newName = NodeFactory.makeId(at, "$" + element_index);
876                  newdecls.add(NodeFactory.makeVarDecl(at, Useful.list(lv), Option.<Expr>some(ExprFactory.makeFieldRef(at,
877                                                                                                                       tempRef,
878                                                                                                                       newName))));
879                  element_index++;
880              }
881              return new RewriteHackList(newdecls);
882          }
883          // Leave singleton VarDecl alone, probably, because it gets properly
884          // handled
885          // at the enclosing block.
886          return visitNode(vd);
887  
888      }

